<template><div class="page listing-page"><button class="btn btn-ghost back-button" @click="$router.back()"><AppIcon name="back"/>Back</button><div class="wizard panel"><div class="progress-row"><span v-for="n in 3" :key="n" :class="{active:step>=n}">{{ step>n?'✓':n }}</span></div><div v-if="step===1"><p class="eyebrow">New listing</p><h1 class="page-title">Where are you selling?</h1><p class="page-subtitle">Choose the marketplace for part #{{ partId||'—' }}.</p><div class="platform-grid"><button v-for="p in platforms" :key="p.value" @click="selectPlatform(p.value)"><span>{{ p.short }}</span><strong>{{ p.label }}</strong><small>{{ p.note }}</small><AppIcon name="arrow"/></button></div></div><form v-else-if="step===2" @submit.prevent="submitListing"><p class="eyebrow">{{ platformLabel }}</p><h1 class="page-title">Listing details</h1><p class="page-subtitle">Add the marketplace details and expected return.</p><div class="form-grid listing-form"><label><span class="form-label">External ID</span><input v-model="form.external_id" class="form-control" required></label><label><span class="form-label">Status</span><select v-model="form.status" class="form-select"><option>DRAFT</option><option>ACTIVE</option><option>SOLD</option></select></label><label class="field-full"><span class="form-label">Listing URL</span><input v-model="form.url" type="url" class="form-control" placeholder="https://" required></label><label><span class="form-label">Price ($)</span><input v-model.number="form.price_c" type="number" min="0" step=".01" class="form-control" required></label><label><span class="form-label">Fees ($)</span><input v-model.number="form.fees_c" type="number" min="0" step=".01" class="form-control" required></label><label><span class="form-label">Listed date/time</span><input v-model="form.listed_datetime" type="datetime-local" class="form-control"></label><label><span class="form-label">Sold date/time</span><input v-model="form.sold_datetime" type="datetime-local" class="form-control"></label></div><div class="wizard-actions"><button type="button" class="btn btn-ghost" @click="step=1">Back</button><button class="btn btn-primary">Create listing</button></div></form><div v-else class="success"><span><AppIcon name="check"/></span><p class="eyebrow">All done</p><h1 class="page-title">Listing created</h1><p>Your {{ platformLabel }} listing has been added to FlipperComplete.</p><div><router-link to="/view-listing" class="btn btn-primary">View listings</router-link><button class="btn btn-ghost" @click="reset">List another</button></div></div></div></div></template>
<script setup>import{ref,computed}from'vue';import superagent from'superagent';import{apiUrl}from'../api';import{useRoute}from'vue-router';import AppIcon from'../components/AppIcon.vue';const route=useRoute(),step=ref(1),platform=ref(''),partId=computed(()=>Number(route.query.part_id)||null);const platforms=[{value:'EBAY',short:'e',label:'eBay',note:'Auction or buy it now'},{value:'FACEBOOK',short:'f',label:'Facebook',note:'Local marketplace'},{value:'CRAIGSLIST',short:'c',label:'Craigslist',note:'Local classifieds'}];const blank=()=>({external_id:'',url:'',price_c:'',fees_c:'',status:'DRAFT',listed_datetime:'',sold_datetime:''}),form=ref(blank()),platformLabel=computed(()=>platforms.find(p=>p.value===platform.value)?.label||'Marketplace');function selectPlatform(v){platform.value=v;step.value=2}async function submitListing(){if(!partId.value)return alert('No part was selected. Return to parts and choose Create listing.');try{const p={part_id:partId.value,platform:platform.value,...form.value,listed_datetime:form.value.listed_datetime?new Date(form.value.listed_datetime).toISOString():null,sold_datetime:form.value.sold_datetime?new Date(form.value.sold_datetime).toISOString():null};await superagent.post(apiUrl('/listings/v1')).send(p);step.value=3}catch{alert('Unable to create this listing. Please check the details and try again.')}}function reset(){step.value=1;platform.value='';form.value=blank()}</script>
<style scoped>.listing-page{max-width:800px;margin:auto}.back-button{margin-bottom:18px}.wizard{padding:clamp(25px,5vw,48px)}.progress-row{display:flex;gap:8px;margin-bottom:40px}.progress-row span{width:31px;height:5px;overflow:hidden;font-size:0;border-radius:5px;background:var(--border)}.progress-row span.active{background:var(--brand)}.platform-grid{display:grid;gap:12px;margin-top:30px}.platform-grid button{position:relative;display:grid;grid-template-columns:46px 1fr auto;align-items:center;gap:14px;padding:16px;border:1px solid var(--border);border-radius:13px;text-align:left;background:var(--bg);color:var(--text);cursor:pointer}.platform-grid button:hover{border-color:var(--brand);background:var(--brand-soft)}.platform-grid button>span{grid-row:1/3;width:42px;height:42px;display:grid;place-items:center;border-radius:11px;background:var(--surface);color:var(--brand);font:800 1.2rem Manrope}.platform-grid strong{align-self:end}.platform-grid small{align-self:start;color:var(--muted)}.platform-grid .app-icon{grid-column:3;grid-row:1/3}.listing-form{margin-top:30px}.wizard-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:26px}.success{text-align:center;padding:35px 0}.success>span{width:64px;height:64px;display:grid;place-items:center;margin:0 auto 24px;border-radius:50%;background:var(--brand-soft);color:var(--brand)}.success>p:not(.eyebrow){color:var(--muted);margin:12px 0 27px}.success>div{display:flex;justify-content:center;gap:10px}.success a{text-decoration:none}</style>
